      {{ warningText }}
    </Message>
  </div>
</template>

<script setup lang="ts">
import CvExpandableTextarea from '@/panel/components/CvExpandableTextarea.vue';

interface Props {
  hasFocusedParagraph: boolean;
  label?: string;
  placeholder?: string;
  warningText?: string;
}

withDefaults(defineProps<Props>(), {
  label: '焦点段落文本',
  placeholder: '在此处输入测试段落，或在聊天中选择任意段落，它会自动在此处填充',
